@import "tailwindcss";

/* the animatable angle behind the liquid-glass card's travelling rim —
   @property has to be declared at the top level or Tailwind drops it */
@property --orbit { syntax: "<angle>"; initial-value: 0deg; inherits: false; }
@keyframes lgc-orbit { to { --orbit: 360deg; } }

@theme {
  /* Brand typeface (Plus Jakarta Sans / JetBrains Mono), injected as CSS vars by
     next/font in app/layout.tsx.
     Mapping them here makes Tailwind's `font-sans` / `font-mono` utilities — and the
     body default below — resolve to Geist, with a graceful system fallback. */
  --font-sans: var(--font-nx-sans), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: var(--font-nx-mono), ui-monospace, "SFMono-Regular", "Menlo", monospace;

  /* ═══════════════════════════════════════════════════════════════════════
     NEXION palette, mapped onto the existing token slots.

     The slot NAMES are kept (brand-*, navy-*, accent-*, slate-*) so all ~4,700
     existing utility usages keep resolving — but every VALUE is the Nexion one.
     Nothing of the previous look survives; the names are just sockets.

     Ground rules carried over from the design canvas:
       - the page ground is DARKER than the cards (navy-950 < navy-900)
       - rims are zero-red blues; a periwinkle rim reads cheap at this saturation
       - accents sit deliberately off full saturation (pulled 14-24 points)
     ═══════════════════════════════════════════════════════════════════════ */

  /* brand ramp — Nexion violet #8c3ae9 at the 500 stop */
  --color-brand-50: #f4ecfe;
  --color-brand-100: #e6d4fb;
  --color-brand-200: #cfaef7;
  --color-brand-300: #b785f2;
  --color-brand-400: #a05cf0;
  --color-brand-500: #8c3ae9;
  --color-brand-600: #7a2fd0;
  --color-brand-700: #6626ad;
  --color-brand-800: #52208a;
  --color-brand-900: #421c6e;

  /* surfaces — 950 is the page ground and is the DARKEST; cards step up */
  --color-navy-950: #000816;
  --color-navy-900: #010f22;
  --color-navy-850: #021428;
  --color-navy-800: #00152f;
  --color-navy-700: #002049;
  --color-navy-600: #002a5e;

  --color-accent-blue: #2f7eef;
  --color-accent-cyan: #14c5e4;

  /* Nexion names, for new work. Same values as the slots above where they
     overlap — use these going forward, the legacy slots stay for old markup. */
  --color-void: #00060f;
  --color-bg: #000816;
  --color-surface: #010f22;
  --color-well: #000c1e;
  --color-hover: #021428;
  --color-side: #00081a;
  --color-rim: #002049;
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
  }
  /* Success badge pop-in (runs once the icon swaps from spinner to check). */
  @keyframes check-pop {
    0% { opacity: 0; transform: scale(0.5); }
    70% { transform: scale(1.08); }
    100% { opacity: 1; transform: scale(1); }
  }
  /* Checkmark stroke draw, timed to start just after check-pop settles. */
  @keyframes check-draw {
    from { stroke-dashoffset: 24; }
    to { stroke-dashoffset: 0; }
  }
  /* Slow ambient glow behind the provisioning icon. Resting state = mid-glow. */
  @keyframes ring-glow {
    0%, 100% { opacity: 0.5; }
    50% { opacity: 1; }
  }
}

/* ══ LIGHT MODE ═══════════════════════════════════════════════════════════
   Everything in this app resolves through the tokens in @theme, so a light
   theme is a token swap rather than a per-component rewrite. `data-theme` is
   set on <html> by components/nx/ThemeToggle.tsx and pre-applied by an inline
   script in app/layout.tsx so the first paint is already correct.

   THE SLATE RAMP IS INVERTED, and that is the load-bearing part. The dark
   theme remaps --color-slate-* so the app's ~4,700 existing `text-slate-*`
   usages resolve to Nexion's blue-tinted ramp, with 50 lightest and 950
   darkest. Body text is `text-slate-300`. Leaving that direction alone in
   light mode would paint pale text on a white page. So in light mode the ramp
   runs the other way: 50 is the darkest ink and 950 the lightest surface,
   which makes `text-slate-300` a readable dark grey and `bg-slate-900` a
   near-white panel, with no call site touched.

   The ground stays DARKER than the cards here too — the same rule the dark
   theme states — so a white card still reads as lifted off the page. */

html[data-theme="light"] {
  color-scheme: light;

  --color-void: #dde5f2;
  --color-bg: #e9eff8;
  --color-surface: #ffffff;
  --color-well: #f3f7fc;
  --color-hover: #e8effa;
  --color-side: #00081a;          /* the rail stays dark — see .nx-dark-island */
  --color-rim: #d3dfef;
  --color-rim-soft: #e3eaf5;
  --color-rim-hi: #bfd0e7;

  /* Accents pulled a little darker so they hold contrast on white. */
  --color-brand-500: #7a2fd0;
  --color-brand-400: #8c3ae9;
  --color-brand-300: #7a2fd0;
  --color-accent-blue: #1f63cc;
  --color-accent-cyan: #0b91ab;
  --color-cyan: #0b91ab;
  --color-blue: #1f63cc;
  --color-violet: #7a2fd0;
  --color-magenta: #b3159c;
  --color-mint: #0a9c6f;
  --color-amber: #b97708;
  --color-rose: #d02a54;

  /* Inverted ramp — 50 is ink, 950 is paper. */
  --color-slate-50: #0a1829;
  --color-slate-100: #10243a;
  --color-slate-200: #18304a;
  --color-slate-300: #26405c;      /* body text */
  --color-slate-400: #4a6382;
  --color-slate-500: #607a99;
  --color-slate-600: #7b91ad;
  --color-slate-700: #a9bbd2;
  --color-slate-800: #d7e1ee;
  --color-slate-900: #e9eff8;
  --color-slate-950: #f5f8fc;

  --color-tx: #081729;
  --color-tx-body: #223449;
  --color-tx-mute: #4a6182;
  --color-tx-dim: #47607f;
  --color-tx-faint: #64778e;

  --fg: #0a1829;
  --fg-muted: #4a6182;

  /* --color-white IS flipped to ink — second reversal, and this is the one
     that stays. Leaving it white made "text-white" (1,640 uses, almost all
     plain heading ink) disappear on every now-light card across the app —
     worse than the problem it was meant to solve, and the more visible bug.
     What actually broke last time was the OPACITY-MODIFIED variants —
     `bg-white/5`, `border-white/10`, `text-white/70` — which resolve through
     this same token and are calibrated as lighteners on a dark base. Those are
     decoupled below via attribute selectors on the literal class text, so they
     stop moving with this token at all. That is the fix; flipping the base
     value back and forth was chasing the wrong variable. */
  --color-white: #0a1829;

  /* The navy ramp is the app's SURFACE ramp — bg-navy-900 (180 uses) and

=== more globals.css around attribute selectors for opacity variants ===
  /* The navy ramp is the app's SURFACE ramp — bg-navy-900 (180 uses) and
     bg-navy-950 (140) are cards, panels and button faces. Left dark while the
     text flipped to ink, they were dark blocks with invisible labels on them.
     Inverted like slate: 950 was the darkest ground, so it becomes the
     lightest paper. */
  --color-navy-950: #ffffff;
  --color-navy-900: #fdfeff;
  --color-navy-850: #f6f9fd;
  --color-navy-800: #eff4fb;
  --color-navy-700: #e0e9f5;
  --color-navy-600: #d0dcee;
}

/* Header sits on the page ground, not the rail ground. */
html[data-theme="light"] header.nx-dark-island { background-color: #000816; }

/* Decorative dark auras. These are violet/blue radial washes tuned against a
   near-black page; over paper the same gradients read as a dirty grey band
   across the top of every hero. Pulled right down rather than removed, so the
   heroes keep a hint of colour. */
html[data-theme="light"] .hero-aura {
  background-image:
    radial-gradient(ellipse 70% 60% at 15% 0%, rgb(111 71 245 / 0.07), transparent 70%),
    radial-gradient(ellipse 60% 50% at 90% 10%, rgb(59 130 246 / 0.05), transparent 70%);
}

/* The page ground: the dark theme lights it from above with two radial pools.
   Light mode keeps the same geometry at a fraction of the strength — enough to
   stop a flat white field, not enough to tint the page. */
/* screen/lighten/"lighter"-composite decorations (GlobeBg, AuroraBg,
   StreamsBg, PlateBg's plates, and every per-page *Aurora canvas) only ever
   ADD light. On a dark page that paints a vivid ribbon or limb; on a light
   page there is no black behind it for the colour to emerge from, so it
   clips straight toward the page colour and reads as a grey smear over
   whatever is there — exactly the "grey radial layer on top of the aurora
   streams" reported. That used to mean hiding all of it in light mode
   (`.nx-mix-additive`, `display: none`) rather than half-rendering a wash —
   but hiding is not a fix, it is losing the decoration outright. The actual
   fix is a per-element theme branch instead of a blanket kill switch:
     - GlobeBg's planet-limb PNG and PlateBg's raster plates have real
       colour to fall back on, so they swap "screen"/"lighten" for normal
       blending at a lower opacity in light mode — see `.nx-globe-arc` below
       and `.nx-plate-additive`.
     - The canvas auroras (AuroraBg, StreamsBg, every *Aurora.tsx component)
       have no such fallback image, so they read the active theme once per
       animation frame in JS and switch `globalCompositeOperation` to
       "source-over" with darker, higher-alpha stops — see auroraTheme.ts.
       Nothing in this stylesheet needs to hide them any more. */
html[data-theme="light"] .nx-globe-arc { mix-blend-mode: normal !important; opacity: 0.4 !important; }

/* PlateBg's screen/lighten raster plates — same fix as .nx-globe-arc, for the
   same reason: these are real images, so light mode swaps the blend mode
   instead of hiding the plate. */
html[data-theme="light"] .nx-plate-additive { mix-blend-mode: normal !important; opacity: 0.4 !important; }

/* The "BUILD / HOST / SCALE / ANYWHERE" deploy-wizard lockup. Base (dark)
   values match what used to be inline on the component. */
.nx-play-lockup { color: #c6daf4; text-shadow: 0 1px 6px rgba(0,6,22,0.95); }
/* A pale ice-blue with a dark contact-shadow, both tuned for sitting on a dark
   hero — the colour was nearly invisible on a light page and the shadow read
   as a smudge rather than adding contrast. */
html[data-theme="light"] .nx-play-lockup {
  color: var(--color-blue);
  text-shadow: none;
}

html[data-theme="light"] body {
  background-image:
    radial-gradient(920px 540px at 88% -12%, rgba(0, 80, 242, 0.07), transparent 62%),
    radial-gradient(700px 460px at 6% 108%, rgba(120, 40, 220, 0.05), transparent 66%);
}

/* ── dark islands ──────────────────────────────────────────────────────────
   The rail and the top bar stay dark in both themes. Rather than hard-coding
   colours into those two components, they re-declare the DARK token values on
   themselves, so their whole subtree — nav rows, the balance card, the search
   field, the account block — inherits dark without any of it knowing a theme
   exists. */
/* ══ The rest of the app ═════════════════════════════════════════════════
   This redesign covers the VPS panel; ~18 other files across Settings,
   Support, Directory, Migrate, Services and the game panel (which the VPS
   panel's own look was modelled on) use the SAME hand-written idiom: a card
   is `bg-[linear-gradient(180deg,rgba(10,22,48,N),rgba(2,7,20,N))]` with a
   `text-white` heading inside it, tuned only ever against a dark page. Editing
   every one of those files individually is a much larger change than this
   pass — these three rules retarget the pattern itself, wherever it appears,
   for light mode only. Dark mode does not match any of these selectors and is
   completely unaffected.

   The attribute selector matches the literal characters Tailwind puts in the
   `class` DOM attribute, which is unescaped there even though the generated
   CSS selector for the same class has to escape the brackets and commas — so
   `[class*="rgba(10,22,48"]` finds it without needing to know the exact
   opacity any given instance used. */
html[data-theme="light"] [class*="rgba(10,22,48"] {
  background-image: linear-gradient(180deg, rgba(255,255,255,.92), rgba(246,249,253,.98)) !important;
  border-color: var(--color-rim);
}
html[data-theme="light"] [class*="rgba(6,14,36"] {
  background: rgba(255,255,255,.85) !important;
}

