970:     text is a literal hex rather than the theme-following `text-white`
1032:  /* `hover:bg-white/[...]`/`hover:text-white` here get compiled by @apply into
1154:    @apply border-slate-200 bg-white text-slate-700;
1158:    @apply border-brand-500/40 bg-white;
1161:    @apply border-slate-200 bg-white/70;
1167:    @apply border-slate-300 bg-white text-slate-800 hover:border-slate-400 hover:bg-slate-50;
1194:    @apply inline-flex cursor-pointer items-center gap-1 rounded-lg px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:text-white;
1197:    @apply text-white;

}
html[data-theme="light"] [class*="rgba(4,11,30"] {
  background: #ffffff !important;
  border-color: var(--color-rim) !important;
}
/* A `text-white` heading is only ever meant as "the readable ink colour" in
   these components — never a colour chosen to sit on a saturated brand
   surface, which is what the VPS panel's own remaining `text-white` spots are
   (and why those were fixed by hand instead of matched here). Scoped to
   descendants of the two card patterns above, so nothing outside them moves. */
html[data-theme="light"] [class*="rgba(10,22,48"] [class~="text-white"],
html[data-theme="light"] [class*="rgba(6,14,36"] [class~="text-white"],
html[data-theme="light"] [class*="rgba(4,11,30"][class~="text-white"] {
  color: var(--color-tx) !important;
}
/* The same subtle-wash idiom my own first pass used before it was fixed
   properly — `bg-white/[0.0N]` as a lightener calibrated for a dark card.
   One flat treatment for all of them rather than one rule per opacity: the
   original values were never trying to be precise, only subtle. */
html[data-theme="light"] [class*="bg-white/[0.0"] {
  background-color: color-mix(in srgb, var(--fg) 6%, transparent) !important;
}

/* The general form of the same fix, for every file this pass did not open.
   `text-white`/`bg-white`/`border-white` (bare, 100% opacity) are headings and
   want ink — that is what flipping the token above does. Anything with a
   slash after "white" is an OPACITY variant — `white/10`, `white/[0.04]`,
   `hover:bg-white/20` — and those want a wash relative to whatever the
   surface actually is now, not a tint of ink-through-transparency. Matched on
   the raw class attribute text, so it does not matter which prefix (hover:,
   sm:, etc.) precedes the utility. Gradient stop utilities (from-white/N,
   via-white/N, to-white/N) are not covered — those set a custom property
   rather than a plain CSS property, so there is no single declaration to
   override this way; decorative sheens, not text, so lower cost left as is. */
/* Islands are EXCLUDED at the selector, not overridden after the fact —
   `revert` does not mean "the value this same rule would have skipped", it
   rolls back to a different cascade origin entirely, so it cannot undo an
   `!important` sibling rule. `:not()` accepts a full selector list including
   descendant combinators, so this reads as "matches, and is not the island and
   is not inside one" in one step. Inside dark chrome, "white at 10% opacity on
   dark" is already correct in both themes and must stay untouched. */
html[data-theme="light"] [class*="bg-white/"]:not(.nx-dark-island, .nx-dark-island *) {
  background-color: color-mix(in srgb, var(--fg) 7%, transparent) !important;
}
html[data-theme="light"] [class*="border-white/"]:not(.nx-dark-island, .nx-dark-island *) {
  border-color: color-mix(in srgb, var(--fg) 16%, transparent) !important;
}
html[data-theme="light"] [class*="text-white/"]:not(.nx-dark-island, .nx-dark-island *) {
  color: color-mix(in srgb, var(--fg) 68%, transparent) !important;
}

=== nx/Provisioning.tsx ===
"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Icon, Plate } from "./Icon";
import { SvcIcon } from "./SvcIcon";

/* The provisioning screen, in the Nexion language.
 *
 * The design sandbox animated this on a TIMER — five stages with hardcoded
 * durations that marched to 100% whether or not anything was happening. That
 * does not survive the port. The platform already records genuine progress:
 * the worker writes a short human label between real, observable command groups
 * (lib/provisioning-step.ts) and returns null when there is no signal yet,
 * explicitly so callers "fall back to generic text rather than claiming false
 * precision". So this reads the real status and the real step, and where it has
 * nothing to report it says something honest instead of inventing a percentage.
 *
 * What IS kept from the design: the mark you just bought held up at full size
 * with the rings travelling out from it, because the wait is the moment the
 * purchase feels real.
 */

export type Phase = "working" | "ready" | "error";

/* The stage list MIRRORS worker/index.ts's real checkpoints, in the order it
   reaches them. Each `key` is a distinct substring of the label the worker
   actually writes to `Server.provisioningStep`:

     "Allocating your server…"        line 590
     "Configuring the network…"       line 620
     "Starting your server…"          line 751
     "Booting the operating system…"  line 763   (skipped under NXEON_SANDBOX)
     "Waiting for network access…"    line 788
     "Starting the game server…"      line 806   (game orders only)

   THIS LIST IS A CONTRACT WITH THE WORKER. It previously carried the design
   sandbox's invented journey — "Installing the image", "Applying security",
   "Finalising setup" — none of which the worker has ever written, while two
   checkpoints it does write matched nothing. In production that meant the
   screen lit up for the first two steps and then fell back to "no signal",
   hiding the progress bar mid-provision. If you add a `step()` call to the
   worker, add its row here; if you rename one, rename the key.

   "Starting your server" and "Starting the game server" both contain
   "starting", so the keys are long enough to tell them apart. */
const STAGES: { key: string; label: string; sub: string; icon: string; gameOnly?: boolean }[] = [
  { key: "allocating", label: "Allocating resources", sub: "Reserving CPU, memory and storage", icon: "cpu" },
  { key: "configuring the network", label: "Configuring network", sub: "Assigning the address and routes", icon: "nodes" },
  { key: "starting your server", label: "Starting the machine", sub: "Powering on your server", icon: "bolt" },
  { key: "booting", label: "Booting the image", sub: "Bringing up the operating system", icon: "download" },
  { key: "waiting for network", label: "Waiting for network", sub: "Confirming it is reachable", icon: "globe2" },
  { key: "starting the game server", label: "Starting the game", sub: "Opening the port to players", icon: "gamepad", gameOnly: true },
  /* LAST, and game-only. `waitOutGameInstall` writes this AFTER the container is
     up (worker/index.ts:1010, called past the "Starting the game server" step),
     because the game itself is still downloading — tens of gigabytes for some
     families. It was added on main in 08a16a1, which stopped healthy servers
     being declared failed for taking a long time over a big install; without a
     row here the customer sat on "Starting the game" through the slowest part
     of the whole process with nothing saying why. */
  { key: "installing the game", label: "Installing the game", sub: "A large download — this is the slow part", icon: "download", gameOnly: true },
];

/* Tips PER PRODUCT. The shared list said "everything here can be resized with
   no downtime" and "backups run daily" — true of a server, false of a domain
   registration, which resizes nothing and backs up nothing. A reassurance that
   does not apply to what the customer just bought is just a false statement in
   a friendly font. */
const TIPS: Record<string, string[]> = {
  vps: [
    "You will get an email with the details the moment this finishes.",
    "Everything here can be resized later with no downtime.",
    "Backups run daily — you can restore any point from the panel.",
  ],
  game: [
    "You will get an email with the details the moment this finishes.",
    "You can change the size of your server later with no downtime.",
    "Mods and settings are yours to manage from the game panel.",
  ],
  hosting: [
    "You will get an email with the details the moment this finishes.",
    "You can point more domains at this account whenever you like.",
  ],
  domains: [
    "You will get an email with the details the moment this finishes.",
    "DNS records can be edited from the domain page as soon as it lands.",
  ],
};

export function Provisioning({
  phase, liveStep, simulate = false, hostname, planName, osName, connectAddress, error, dashboardHref,
  service = "vps", specs = [], slots = null, regionName = null,
}: {
  phase: Phase;
  /** Which product this is, so the held-up mark is the one they bought. */
  service?: "vps" | "game" | "hosting" | "domains";
  /** Real plan resources, for the "coming online" panel. Empty = panel hidden. */
  specs?: { icon: string; text: string }[];
  /** Real player-slot count on a game order. Null = not a game / unknown. */
  slots?: number | null;
  regionName?: string | null;
  /** The worker's own label for what it is doing. Null = no signal yet. */
  liveStep: string | null;
  /**
   * SANDBOX ONLY. There is no hypervisor here, so the worker never provisions
   * and never writes a progress step — which left this screen visibly inert and
   * impossible to judge as a design. When set, the stages advance on a timer.
   *
   * The server page sets it ONLY under NXEON_SANDBOX and only when there is no
   * real step to show, so production always renders from the worker's own
   * reporting. A timed bar in front of a paying customer is a lie told smoothly;
   * in front of a designer with no hypervisor it is just a preview.
   */
  simulate?: boolean;
  hostname: string;
  planName: string;
  osName: string;
  connectAddress?: string | null;
  error?: string | null;
  dashboardHref: string;
}) {
  const [tip, setTip] = useState(0);
  useEffect(() => {
    if (phase !== "working") return;
    const t = setInterval(() => setTip((n) => (n + 1) % (TIPS[service] ?? TIPS.vps).length), 5200);
    return () => clearInterval(t);
  }, [phase, service]);

  /* Only the stages this product actually goes through — the game server's own
     port opening is not a step a VPS ever reaches. */
  /* Domains have NO stage list. Registration is synchronous — the registrar
     answers yes or no in one call and there is no async job writing checkpoints
     — so showing a five-step march would be theatre. The mark, the title and the
     tip carry the wait instead, and the ready state does the real work. */
  const stages = service === "domains"
    ? []
    : STAGES.filter((s) => !s.gameOnly || service === "game");

  /* Which stage the worker's label corresponds to. -1 when it has not said
     anything yet, which is a real state and not "0% done". */
  const matched = liveStep
    ? stages.findIndex((s) => liveStep.toLowerCase().includes(s.key))
    : -1;

  /* Progress only ever moves FORWARD.
   *
   * A label this build does not recognise — the worker gained a checkpoint, or
   * was renamed — used to read as -1, which threw the screen back to "nothing
   * reported yet" and made the bar vanish mid-provision. An unknown label means
   * work is still happening, so hold the furthest stage actually seen rather
   * than telling the customer we have lost track. */
  const [reported, setReported] = useState(-1);
  useEffect(() => {
    if (matched > reported) setReported(matched);
  }, [matched, reported]);

  /* Sandbox preview only — see `simulate`. */
  const [fake, setFake] = useState(0);
  useEffect(() => {
    if (!simulate || phase !== "working") return;
    const t = setInterval(() => setFake((n) => (n + 1) % (stages.length + 1)), 2200);
    return () => clearInterval(t);
  }, [simulate, phase]);

  const active = simulate ? fake : reported;

  /* Real completion, not a clock: the fraction of the stage list the worker has
     actually reported past. `active < 0` means it has told us NOTHING yet, which
     is a real state — the bar is hidden rather than parked at a made-up 0%. */
  const known = active >= 0;
  const pct = phase === "ready" ? 100
            : known ? Math.round((Math.min(active, stages.length) / stages.length) * 100)
                    : null;

  if (phase === "error") {
    return (
      <Shell service={service} hostname={hostname} planName={planName} osName={osName} tone="rose">
        <div className="flex flex-col items-center gap-2 text-center">
          <Icon name="warntriangle" size={26} className="text-rose" />
          <span className="text-[17px] font-extrabold text-white">Provisioning failed</span>
          <span className="max-w-[440px] text-[12.5px] leading-[1.5] text-tx-mute">
            {/* the worker's real reason, never a generic apology */}
            {error || "The server could not be built. Support has been notified."}
          </span>
          <Link href="/dashboard/support" className="btn mt-2 h-[40px] px-5 text-[13px]">
            Contact support <span className="arw">→</span>
          </Link>
        </div>
      </Shell>
    );
  }

  if (phase === "ready") {
    return (
      <Shell service={service} hostname={hostname} planName={planName} osName={osName} tone="mint" settled>
        <div className="flex w-full flex-col items-center gap-4">
          <div className="flex flex-col items-center gap-2 text-center">
            <Icon name="checkcircle" size={28} className="text-mint" />
            <span className="text-[19px] font-extrabold tracking-[-0.02em] text-white">
              {service === "domains" ? "The domain is yours"
                : service === "hosting" ? "Your hosting is ready"
                : "Your server is live"}
            </span>
            <span className="text-[13px] text-tx-mute">
              {service === "domains"
                ? `${hostname} is registered and pointing at Nxeon.`
                : `${hostname} is up and ready${regionName ? ` in ${regionName}` : ""}.`}
            </span>
          </div>

          <div className="nx-rise flex w-full max-w-[520px] flex-col gap-3">
            <div className="card flex flex-col gap-2.5 p-4 text-left">
              <span className="text-[12.5px] font-bold text-white">Connection details</span>
              {/* Every row is a value this page already holds. There is no
                  "Charged today" line: the amount actually taken lives on the
                  invoice, and re-deriving it here would be a second number free
                  to disagree with the one the customer was billed. */}
              {connectAddress && <Row k={service === "game" ? "Connect" : "Address"} v={connectAddress} />}
              <Row k={service === "domains" ? "Registration" : "Plan"}
                   v={`${planName}${regionName ? ` · ${regionName}` : ""}`} />
              {service !== "game" && service !== "domains" && osName && <Row k="Image" v={osName} />}
            </div>
            {/* Only appears once the server is genuinely RUNNING — the whole
                point of this screen is that the customer is not handed controls
                for a machine that does not exist yet. */}
            <Link href={dashboardHref} className="btn grid h-[48px] w-full place-items-center text-[14px]">
              {service === "domains" ? "Manage the domain" : "Open the panel"} <span className="arw">→</span>
            </Link>
          </div>
        </div>
      </Shell>
    );
  }

  return (
    <Shell service={service} hostname={hostname} planName={planName} osName={osName} tone="blue">
      <div className="flex w-full flex-col items-center gap-4">
        <div className="flex flex-col items-center gap-1 text-center">
          <span className="text-[19px] font-extrabold tracking-[-0.02em] text-white">
            {service === "domains" ? "Registering your domain"
              : service === "hosting" ? "Setting up your hosting"
              : "Building your server"}
          </span>
          <span className="text-[12.5px] text-tx-mute">
            {/* The worker's own words when it has them. No invented percentage:
                a bar that moves on a timer is a lie told smoothly. */}
            {liveStep
              ?? (simulate && active >= 0 && active < stages.length
                    ? stages[active].sub
                    : "Getting started — this usually takes about a minute.")}
          </span>
        </div>

        {/* Progress, only once the worker has actually reported something. A bar
            that fills on a timer is a lie told smoothly, so when there is no
            signal there is no bar — not a bar sitting at zero. */}
        {pct !== null && (
          <div className="flex w-full max-w-[520px] flex-col gap-2">
            <div className="bar w-full">
              <i style={{ width: `${pct}%` }} />
            </div>
            <div className="flex items-center justify-between text-[11.5px]">
              <span className="text-tx-faint">
                {active < stages.length ? stages[Math.max(0, active)].label : "Finishing up"}
              </span>
              <span className="font-bold text-white">{pct}%</span>
            </div>
          </div>
        )}

        <ul className="flex w-full max-w-[520px] flex-col gap-1.5 text-left">
          {stages.map((s, n) => {
            const done = active > n;
            const now = active === n;
            return (
              <li key={s.key}
                  /* `now`/`done` used to be flat literal navy washes
                     (rgba(8,32,68,.6) / rgba(4,22,42,.4)), tuned only ever
                     against a dark page — on a light one that alpha-blends to
                     a flat grey slab with no accent left in it. color-mix
                     against the accent tokens (already theme-aware) keeps the
                     same "soft tinted card" idea in both themes instead. */
                  className={"flex items-center gap-3.5 rounded-[11px] border px-3 py-2.5 transition-colors duration-300 " +
                    (now ? "border-[color-mix(in_srgb,var(--color-blue)_45%,transparent)] bg-[color-mix(in_srgb,var(--color-blue)_12%,transparent)]"
                         : done ? "border-rim-soft bg-[color-mix(in_srgb,var(--color-mint)_9%,transparent)]"
                                : "border-transparent opacity-45")}>
                <span className="grid h-[28px] w-[28px] flex-none place-items-center">
                  {done ? (
                    <span className="nx-pop grid h-[28px] w-[28px] place-items-center rounded-full
                                     bg-[linear-gradient(135deg,#14c5e4,#11c88e)] text-[#012019]">
                      {/* tone="inherit": the icon otherwise forces its own
                          mint-green class, which on this cyan/green gradient is
                          a green tick on a green disc — unreadable in either
                          theme. The dark ink set above is what should show. */}
                      <Icon name="checkcircle" size={16} tone="inherit" />
                    </span>
                  ) : now ? (
                    /* The spinner is the design's one honest animation here: it
                       says "this step is in flight", which is exactly what the
                       worker reported. It does not imply a rate. */
                    <span className="nx-spin h-[24px] w-[24px] rounded-full border-2 border-[rgba(120,170,235,0.25)]
                                     border-t-[#5fd0ff]" />
                  ) : (
                    <span className="h-[20px] w-[20px] rounded-full border border-rim-hi" />
                  )}
                </span>
                <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                  <span className={"trunc text-[13px] font-bold " + (done || now ? "text-white" : "text-tx-dim")}>
                    {s.label}
                  </span>
                  <span className="trunc text-[11.3px] text-tx-faint">{s.sub}</span>
                </span>
                <Plate name={s.icon} size={26} tone={now ? "c" : ""} glow={done || now} className="flex-none" />
              </li>
            );
          })}
        </ul>

        <Detail service={service} specs={specs} slots={slots} pct={(pct ?? 0) / 100} />

        <div className="card flex w-full max-w-[520px] items-start gap-3 p-3.5 text-left">
          <Plate name="sparkles" size={22} />
          <span className="flex min-w-0 flex-col gap-0.5">
            <span className="text-[12px] font-bold text-white">While you wait</span>
            <span key={tip} className="nx-rise text-[11.8px] leading-[1.5] text-tx-mute">
              {(TIPS[service] ?? TIPS.vps)[tip % (TIPS[service] ?? TIPS.vps).length]}
            </span>
          </span>
        </div>
      </div>
    </Shell>
  );
}

/* The mark, held up while the work happens. */
function Shell({
  children, hostname, planName, osName, tone, settled, service = "vps",
}: {
  children: React.ReactNode;
  hostname: string; planName: string; osName: string;
  tone: "blue" | "mint" | "rose";
  settled?: boolean;
  service?: "vps" | "game" | "hosting" | "domains";
}) {
  const glow = tone === "mint" ? "rgba(17,200,142,0.24)"
             : tone === "rose" ? "rgba(239,66,108,0.22)"
             : "rgba(60,150,255,0.24)";
  return (
    <div className="mx-auto flex w-full max-w-[720px] flex-col items-center gap-6 py-6 text-center">
      <div className="relative grid h-[150px] w-[150px] place-items-center">
        {!settled && tone === "blue" && (
          <>
            <span aria-hidden className="nx-ring absolute h-[112px] w-[112px] rounded-full border border-[rgba(90,190,255,0.55)]" />
            <span aria-hidden className="nx-ring absolute h-[112px] w-[112px] rounded-full border border-[rgba(200,110,255,0.45)]"
                  style={{ animationDelay: "1.2s" }} />
          </>
        )}
        <span aria-hidden className="absolute h-[120px] w-[120px] rounded-full"
              style={{ background: `radial-gradient(circle, ${glow} 0%, transparent 66%)` }} />
        {/* The mark for the product they bought. This was hardcoded to "vps",
            so a game order was handed up the VPS cube instead of the pad. */}
        <SvcIcon name={service} size={104} className={settled ? "" : "nx-float relative"} />
      </div>

      {children}

      <div className="flex flex-wrap items-center justify-center gap-x-4 gap-y-1.5 text-[11.5px] text-tx-faint">
        <span className="flex items-center gap-1.5"><Icon name="server" size={13} />{hostname}</span>
        <span className="flex items-center gap-1.5"><Icon name="cube" size={13} />{planName}</span>
        <span className="flex items-center gap-1.5"><Icon name="linux" size={13} />{osName}</span>
      </div>
    </div>
  );
}


function Row({ k, v }: { k: string; v: string }) {
  return (
    <div className="flex items-baseline justify-between gap-3">
      <span className="text-[12px] text-tx-faint">{k}</span>
      <span className="mono trunc text-[12.5px] font-bold text-white">{v}</span>
    </div>
  );
}

/* What is actually being built, per product.
 *
 * The stage list says which step we are on; this says what is APPEARING. Both
 * read the SAME real progress figure — there is no second clock — so a panel
 * can never show a resource online while the stage list still says the image is
 * being written.
 *
 * Two things in the design's version are deliberately not reproduced: its
 * "world seed", which it fabricated by hashing the game's name, and its list of
 * mailbox addresses (`you@`, `hello@`, `billing@`), which the customer never
 * asked for. Both render as fact and neither is one.
 */
function Detail({ service, specs, slots, pct }: {
  service: "vps" | "game" | "hosting" | "domains";
  specs: { icon: string; text: string }[];
  slots: number | null;
  pct: number;
}) {
  const Card = ({ label, children }: { label: string; children: React.ReactNode }) => (
    <div className="card flex w-full max-w-[520px] flex-col gap-2.5 p-3.5 text-left">
      <span className="text-[11px] font-bold uppercase tracking-[0.11em] text-tx-faint">{label}</span>
      {children}
    </div>
  );

  if (service === "game") {
    if (!slots || slots < 1) return null;
    /* Capped at 32 pips so a 150-slot server does not paint six rows of squares;
       the LABEL still states the real number. */
    const shown = Math.min(slots, 32);
    const lit = Math.round(shown * pct);
    return (
      <Card label={`Preparing ${slots} player slot${slots === 1 ? "" : "s"}`}>
        <div className="flex flex-wrap gap-1.5">
          {Array.from({ length: shown }, (_, i) => (
            <span key={i}
                  className={"h-[13px] w-[13px] rounded-[4px] transition-all duration-500 " +
                    (i < lit ? "bg-[linear-gradient(135deg,#14c5e4,#6f2ee0)]"
                             : "border border-rim-hi bg-well")}
                  style={{ transitionDelay: `${(i % 8) * 40}ms` }} />
          ))}
        </div>
      </Card>
    );
  }

  /* No "resources coming online" for a domain: nothing is being provisioned. */
  if (service === "domains" || !specs.length) return null;
  /* Each resource on its own ramp so they do not move in lockstep, but all
     driven by the one real percentage and clamped to it. */
  const rows = specs.slice(0, 3).map((sp, i) => ({
    ...sp, at: Math.max(0, Math.min(1, (pct - i * 0.12) / 0.62)),
  }));
  return (
    <Card label="Resources coming online">
      {rows.map((r) => (
        <div key={r.text} className="flex items-center gap-3">
          <Plate name={r.icon} size={22} className="flex-none" />
          <span className="w-[124px] flex-none text-[12px] text-tx-body">{r.text}</span>
          <span className="h-[5px] flex-1 overflow-hidden rounded-full bg-well">
            <span className="block h-full rounded-full transition-[width] duration-700 ease-out"
                  style={{ width: `${r.at * 100}%`, background: "linear-gradient(90deg,#2f7eef,#3fbcd8)" }} />
          </span>
          <span className="w-[34px] flex-none text-right text-[11px] font-bold text-tx-dim">
            {Math.round(r.at * 100)}%
          </span>
        </div>
      ))}
    </Card>
  );
}

