import Link from "next/link";
import type { ReactNode } from "react";

/**
 * DeployButton — the single, sleek "Deploy" CTA used on every portal service page
 * (Servers, Shared Hosting, Game Servers, …) so they read consistently. Styling +
 * animation live in the `.btn-deploy` class (app/globals.css): a pill with an
 * animated gradient-shift, a one-shot shimmer sweep on hover, and an arrow that
 * nudges right. Reduced-motion users get the static gradient. Pass a `href` to the
 * deploy hub (optionally with `?product=`) and a plain label as children — the
 * component supplies the animated arrow itself.
 */
export function DeployButton({
  href,
  children,
  className = "",
}: {
  href: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <Link href={href} className={`btn-deploy ${className}`}>
      <span>{children}</span>
      <span className="dep-arrow text-[1.05em] leading-none" aria-hidden>
        →
      </span>
    </Link>
  );
}

