import { fmtMoney } from "@/components/ui/primitives";

export type GameTierSummary = {
  id: string;
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  slots: number | null;
  priceCents: number;
  termMonths: number;
};

/**
 * Game-server "Resize & storage" card.
 *
 * INFORMATIONAL, NOT SELF-SERVICE. A game tier (`GamePlan`) is sold as a fixed,
 * flat-price bundle — `lib/resize.ts` refuses `resizeQuote` outright for any
 * server with a `gamePlanId` ("Game server plans are fixed bundles — switch
 * tiers from the game server's own settings, or contact support"), and
 * `lib/renewal-charge.ts` bills a game plan at ONE flat price with no per-GB
 * disk or backup add-on lines ever added on top ("a game plan is all-in").
 *
 * Wiring the VPS `ResizePicker`/`AddStorage` in here unmodified would either
 * (a) let a customer "resize" onto a raw VPS `Plan` that has nothing to do with
 * what they actually bought, hitting the ResizeError above every time, or
 * (b) let them buy extra disk that is charged once and then rides free on every
 * renewal forever, since `renewalCharge` never re-bills disk for a flat game
 * plan. Neither is a real feature — so this card gives the customer the
 * information those actions can't: what they're on, what else exists, and how
 * to actually move (support does it manually, preserving the world/data).
 */
export function GameTierInfo({
  hostname,
  current,
  otherTiers,
  effectiveDiskGB,
  extraDiskGB,
  supportHref = "/dashboard/support",
}: {
  hostname: string;
  current: GameTierSummary;
  /** Other ACTIVE tiers in the same game family, cheapest first. */
  otherTiers: GameTierSummary[];
  /** plan disk + any extra disk this server holds. */
  effectiveDiskGB: number;
  extraDiskGB: number;
  supportHref?: string;
}) {
  const monthly = Math.round(current.priceCents / Math.max(1, current.termMonths));

  return (
    <div className="card space-y-4">
      <div>
        <h3 className="font-semibold">Resize &amp; storage</h3>
        <p className="mt-1 max-w-xl text-sm text-slate-400">
          Game server tiers are fixed, all-in bundles — CPU, RAM, disk, slots and price move
          together as a set, so they can&apos;t be resized piecemeal the way a VPS plan can.
        </p>
      </div>

      <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="text-sm font-medium text-slate-200">{current.name}</p>
          <span className="rounded-full border border-brand-500/30 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-brand-300">
            current tier
          </span>
        </div>
        <dl className="mt-3 grid grid-cols-2 gap-x-4 gap-y-1.5 text-xs text-slate-400 sm:grid-cols-4">
          <div>
            <dt className="text-slate-500">CPU</dt>
            <dd className="text-slate-200">{current.cpuCores} vCPU</dd>
          </div>
          <div>
            <dt className="text-slate-500">RAM</dt>
            <dd className="text-slate-200">{(current.ramMB / 1024).toFixed(current.ramMB % 1024 ? 1 : 0)} GB</dd>
          </div>
          <div>
            <dt className="text-slate-500">Disk</dt>
            <dd className="text-slate-200">
              {effectiveDiskGB} GB
              {extraDiskGB > 0 && <span className="text-slate-500"> ({current.diskGB} + {extraDiskGB})</span>}
            </dd>
          </div>
          {current.slots != null && (
            <div>
              <dt className="text-slate-500">Slots</dt>
              <dd className="text-slate-200">{current.slots}</dd>
            </div>
          )}
        </dl>
        <p className="mt-2 text-xs text-slate-500">{fmtMoney(monthly)}/mo</p>
      </div>

      {otherTiers.length > 0 && (
        <div>
          <p className="section-label mb-2">Other tiers in this game family</p>
          <div className="space-y-2">
            {otherTiers.map((t) => {
              const tMonthly = Math.round(t.priceCents / Math.max(1, t.termMonths));
              const bigger = t.ramMB > current.ramMB || t.diskGB > current.diskGB;
              return (
                <div
                  key={t.id}
                  className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-white/[0.06] bg-navy-950/40 px-3 py-2 text-xs"
                >
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-slate-300">
                    <span className="font-medium text-slate-200">{t.name}</span>
                    <span className="text-slate-500">
                      {t.cpuCores} vCPU · {(t.ramMB / 1024).toFixed(t.ramMB % 1024 ? 1 : 0)} GB · {t.diskGB} GB
                      {t.slots != null ? ` · ${t.slots} slots` : ""}
                    </span>
                  </div>
                  <span className={bigger ? "font-semibold text-emerald-300" : "font-semibold text-slate-300"}>
                    {fmtMoney(tMonthly)}/mo
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      )}

      <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3 text-xs text-slate-400">
        Want a bigger (or smaller) tier, or more disk on {hostname}? Our team moves you across
        manually, keeping your world/data intact —{" "}
        <a
          href={supportHref}
          className="text-brand-300 underline decoration-brand-500/40 underline-offset-2 hover:text-brand-200"
        >
          contact support
        </a>
        .
      </div>
    </div>
  );
}
